// Transform weather data for HoneyGo pricing
const weather = $input.first().json;

let multiplier = 1.0;
let reasoning = 'Normal weather conditions';

// Temperature adjustments
if (weather.main.temp > 100) {
  multiplier += 0.15;
  reasoning = 'Extreme heat increases demand';
} else if (weather.main.temp < 32) {
  multiplier += 0.1;
  reasoning = 'Cold weather increases demand';
}

// Weather condition adjustments
const condition = weather.weather[0].main.toLowerCase();
if (condition.includes('rain')) {
  multiplier += 0.25;
  reasoning = 'Rain increases ride demand';
} else if (condition.includes('snow')) {
  multiplier += 0.5;
  reasoning = 'Snow significantly impacts driving';
} else if (condition.includes('storm')) {
  multiplier += 0.4;
  reasoning = 'Storm conditions reduce driver availability';
}

// Visibility adjustments
if (weather.visibility < 1000) {
  multiplier += 0.2;
  reasoning += ', low visibility';
}

return {
  city: weather.name,
  temperature_f: Math.round(weather.main.temp),
  conditions: weather.weather[0].main,
  description: weather.weather[0].description,
  humidity: weather.main.humidity,
  wind_mph: Math.round(weather.wind.speed),
  visibility_miles: Math.round(weather.visibility / 1609),
  pricing_multiplier: Math.round(multiplier * 100) / 100,
  reasoning: reasoning,
  timestamp: new Date().toISOString()
};
